package com.bank.archive;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ArrayCopyDemo {
    private static final Logger log = Logger.getLogger(ArrayCopyDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        BigDecimal[] original = {
            new BigDecimal("1000.00"),
            new BigDecimal("2000.00"),
            new BigDecimal("3000.00")
        };

        ArchiveService archive = new ArchiveService();
        BigDecimal[] backup = archive.backup(original);
        log.info(() -> "Archive created: " + Arrays.toString(backup));

        // Recalculation overwrites the original (simulated)
        original[0] = new BigDecimal("1100.00");
        log.info(() -> "Original after recalculation: " + Arrays.toString(original));
        log.info(() -> "Archive still safe:            " + Arrays.toString(backup));
    }
}

class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
