package com.bank.archive;

import java.math.BigDecimal;
import java.util.Arrays;

class ArchiveService {

    // Manual loop copy — clear and explicit. O(n) time, O(n) space.
    BigDecimal[] backup(BigDecimal[] src) {
        if (src == null) throw new IllegalArgumentException("source is null");
        BigDecimal[] dest = new BigDecimal[src.length];     // fresh array
        for (int i = 0; i < src.length; i++) {
            dest[i] = src[i];                               // copy each reference (safe: immutable)
        }
        return dest;
    }

    // Built-in alternative: Arrays.copyOf does the same in one call.
    BigDecimal[] backupFast(BigDecimal[] src) {
        if (src == null) throw new IllegalArgumentException("source is null");
        return Arrays.copyOf(src, src.length);
    }
}
